window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["kubernetes-33-scheduling-amp-br-node-management"]={"html":"Scheduling &amp; Node Management — Kubernetes Book 04\n\n\n<a href=\"#toc\">▤ TOC</a>\n\n\n<div class=\"page cover\">\n<div class=\"orb\"></div>\n<div class=\"orb\"></div>\n<div class=\"wheel\">🎯</div>\n<h1 id=\"scheduling-amp-node-management\">SCHEDULING &amp;<br />NODE MANAGEMENT</h1>\n<div class=\"sub\">Book 04 of the series — inside the Scheduler's decision: filter, score, bind. The full taints &amp; tolerations system, node/pod affinity, topology spread, priority &amp; preemption, and the maintenance discipline: cordon, drain, static Pods.</div>\n<div class=\"row\">\n<div class=\"glass\">🎯 Scheduler<small>filter → score → bind</small></div>\n<div class=\"glass\">🚧 Taints<small>all 3 effects</small></div>\n<div class=\"glass\">🔑 Tolerations<small>the keys</small></div>\n<div class=\"glass\">🧲 Affinity<small>node &amp; pod</small></div>\n</div>\n<div class=\"row\">\n<div class=\"glass\">⚖️ Spread<small>zones &amp; skew</small></div>\n<div class=\"glass\">👑 Priority<small>+ preemption</small></div>\n<div class=\"glass\">🛠️ Drain<small>maintenance</small></div>\n<div class=\"glass\">🪨 Static Pods<small>kubelet-born</small></div>\n</div>\n<div class=\"ver\">K8S KNOWLEDGE BASE · BOOK 04 · CONTINUES BOOKS 01–03 · 2026</div>\n</div>\n\n\n<div class=\"page\">\n<div class=\"pghead\"><span class=\"chip\">📖</span><h2 id=\"contents-click-any-row\">Contents — click any row</h2><span class=\"dbadge\">7 parts · 20 chapters</span></div>\n<div class=\"tocgrid\">\n<div class=\"tocpart\">Part I · The Scheduler's Mind</div>\n<a href=\"#ch01\"><span class=\"cb\"></span><span class=\"tnum\">CH 01</span>How Scheduling Works<span class=\"dots\"></span><span class=\"tp\">p.3</span></a>\n<a href=\"#ch02\"><span class=\"cb\"></span><span class=\"tnum\">CH 02</span>The Scheduling Toolbox<span class=\"dots\"></span><span class=\"tp\">p.4</span></a>\n<div class=\"tocpart\">Part II · Taints &amp; Tolerations — Full System</div>\n<a href=\"#ch03\"><span class=\"cb\"></span><span class=\"tnum\">CH 03</span>Taints — Effects &amp; Use Cases<span class=\"dots\"></span><span class=\"tp\">p.5</span></a>\n<a href=\"#ch04\"><span class=\"cb\"></span><span class=\"tnum\">CH 04</span>Tolerations — Operators &amp; tolerationSeconds<span class=\"dots\"></span><span class=\"tp\">p.6</span></a>\n<a href=\"#ch05\"><span class=\"cb\"></span><span class=\"tnum\">CH 05</span>Well-Known Taints — The Cluster's Own<span class=\"dots\"></span><span class=\"tp\">p.7</span></a>\n<div class=\"tocpart\">Part III · Affinity &amp; Spread</div>\n<a href=\"#ch06\"><span class=\"cb\"></span><span class=\"tnum\">CH 06</span>nodeSelector &amp; Node Affinity<span class=\"dots\"></span><span class=\"tp\">p.8</span></a>\n<a href=\"#ch07\"><span class=\"cb\"></span><span class=\"tnum\">CH 07</span>Pod Affinity &amp; Anti-Affinity<span class=\"dots\"></span><span class=\"tp\">p.9</span></a>\n<a href=\"#ch08\"><span class=\"cb\"></span><span class=\"tnum\">CH 08</span>topologySpreadConstraints<span class=\"dots\"></span><span class=\"tp\">p.10</span></a>\n<div class=\"tocpart\">Part IV · Priority &amp; Eviction</div>\n<a href=\"#ch09\"><span class=\"cb\"></span><span class=\"tnum\">CH 09</span>Priority Classes &amp; Preemption<span class=\"dots\"></span><span class=\"tp\">p.11</span></a>\n<div class=\"tocpart\">Part V · Node Operations</div>\n<a href=\"#ch10\"><span class=\"cb\"></span><span class=\"tnum\">CH 10</span>Cordon, Drain &amp; Uncordon<span class=\"dots\"></span><span class=\"tp\">p.12</span></a>\n<a href=\"#ch11\"><span class=\"cb\"></span><span class=\"tnum\">CH 11</span>Static Pods<span class=\"dots\"></span><span class=\"tp\">p.13</span></a>\n<div class=\"tocpart\">Part VI · Labs</div>\n<a href=\"#lab1\"><span class=\"cb\"></span><span class=\"tnum\">LAB 1</span>Node Affinity — Required vs Preferred<span class=\"dots\"></span><span class=\"tp\">p.14</span></a>\n<a href=\"#lab2\"><span class=\"cb\"></span><span class=\"tnum\">LAB 2</span>Anti-Affinity — Prove the Separation<span class=\"dots\"></span><span class=\"tp\">p.15</span></a>\n<a href=\"#lab3\"><span class=\"cb\"></span><span class=\"tnum\">LAB 3</span>Priority &amp; Preemption Live<span class=\"dots\"></span><span class=\"tp\">p.16</span></a>\n<a href=\"#lab4\"><span class=\"cb\"></span><span class=\"tnum\">LAB 4</span>The Maintenance Cycle<span class=\"dots\"></span><span class=\"tp\">p.17</span></a>\n<div class=\"tocpart\">Part VII · Prove It</div>\n<a href=\"#quiz\"><span class=\"cb\"></span><span class=\"tnum\">QUIZ</span>Self-Check Quiz<span class=\"dots\"></span><span class=\"tp\">p.18</span></a>\n<a href=\"#key\"><span class=\"cb\"></span><span class=\"tnum\">KEY</span>Answer Key + Scoring<span class=\"dots\"></span><span class=\"tp\">p.19</span></a>\n<a href=\"#gloss\"><span class=\"cb\"></span><span class=\"tnum\">GLOSS</span>Glossary<span class=\"dots\"></span><span class=\"tp\">p.20</span></a>\n<a href=\"#cheat\"><span class=\"cb\"></span><span class=\"tnum\">CHEAT</span>One-Page Cheat Sheet<span class=\"dots\"></span><span class=\"tp\">p.21</span></a>\n<a href=\"#finale\"><span class=\"cb\"></span><span class=\"tnum\">FINALE</span>Where to Next → Book 05<span class=\"dots\"></span><span class=\"tp\">p.22</span></a>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Assumes Books 01–03.</b> Book 01 · CH 07 + Lab 5 gave you taints' first taste; CH 23 showed Pending = \"the Scheduler said no\". This book opens the black box: <i>every reason the Scheduler says yes or no, and every knob you own</i>.</div></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span>◀ cover · start ▶</span><span>Page 2</span></div>\n</div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 01</span><h2 id=\"how-scheduling-works\">🎯 How Scheduling Works</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The Scheduler is a control loop (Book 01 · CH 02) with one job: for each <b>unscheduled</b> Pod, pick the best feasible Node and <b>bind</b> the Pod to it. Every decision is a three-stage funnel:</p>\n<div class=\"zone zone-cp\">\n<div class=\"zlabel\">The funnel — every Pod, every time</div>\n<div class=\"rowc\"><div class=\"kchip\">🆕 Pod appears<small> schedulerName: default</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-rose\">1 · FILTER<small>feasible nodes only</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-amber\">2 · SCORE<small>rank the survivors</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-emerald\">3 · BIND<small>write it down</small></div></div>\n<p>filter kills nodes that <i>can't</i> take the Pod · score ranks nodes that <i>can</i> · the highest score wins</p>\n</div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">1 · FILTER — hard constraints</div>\n<ul>\n<li>Pod's <b>requests</b> fit the node's allocatable (Book 02 · CH 14)</li>\n<li><b>Taints</b> tolerated? (Part II of this book)</li>\n<li><b>nodeSelector / required affinity</b> match?</li>\n<li>Ports, volumes, hostNetwork conflicts</li>\n</ul>\n<p><b>Zero nodes survive → Pod stays Pending.</b> This is the #1 cause.</p></div>\n<div class=\"card\"><div class=\"zlabel\">2 · SCORE — soft preferences</div>\n<ul>\n<li><b>Preferred affinity/anti-affinity</b> weights</li>\n<li><b>Spreading</b> vs packing balance (CH 08)</li>\n<li>Image locality (image already pulled?), pod spread across zones…</li>\n</ul>\n<p>Every plugin votes 0–100; sum decides. <b>Ties → random.</b></p></div>\n</div>\n<div class=\"term mini\"><span class=\"g\"># the binding is a real API object — you can see the decision:</span>\n<span class=\"p\">$</span> kubectl get pod web -o jsonpath=<span class=\"m\">'{.spec.nodeName}'</span>\nminikube</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Scheduling is one-time, not a lease:</b> once bound, the Scheduler never reconsiders. If the node degrades, the <b>kubelet</b> and node-lifecycle controller react (taints → evict) — the Scheduler only picks <i>new</i> placements. Re-scheduling happens only if the Pod <i>dies and is recreated</i>.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> <i>Filter decides IF a node can; Score decides WHICH node should; Bind makes it official</i> — and every tool in this book plugs into exactly one of those stages.</div></div>\n<p>⏭️ The full knob inventory — <a href=\"#ch02\">CH 02: The Scheduling Toolbox</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#toc\">▤ TOC</a> · <a href=\"#ch02\">next ▶</a></span><span>Page 3</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 02</span><h2 id=\"the-scheduling-toolbox\">🧰 The Scheduling Toolbox</h2><span class=\"dbadge\">🟢 5 MIN</span></div>\n<p>Five mechanisms decide placement. Knowing <i>which stage</i> each one acts in tells you which to reach for:</p>\n<div class=\"table-scroll\"><table>\n<tr><th>Tool</th><th>Stage</th><th>Hard or soft?</th><th>One-line job</th></tr>\n<tr><td><b>Resources (requests)</b></td><td>Filter + Score</td><td>hard (capacity)</td><td>\"this Pod needs 500Mi / 250m somewhere\"</td></tr>\n<tr><td><b>Taints + Tolerations</b></td><td>Filter</td><td>hard (node repels)</td><td>\"keep ordinary Pods OFF this node\"</td></tr>\n<tr><td><b>Node affinity / nodeSelector</b></td><td>Filter / Score</td><td>both (required / preferred)</td><td>\"this Pod WANTS certain nodes\"</td></tr>\n<tr><td><b>Pod (anti-)affinity</b></td><td>Filter / Score</td><td>both</td><td>\"co-locate / separate from other Pods\"</td></tr>\n<tr><td><b>topologySpread</b></td><td>Score (+ filter)</td><td>soft or hard</td><td>\"spread evenly across zones/nodes\"</td></tr>\n</table></div>\n<div class=\"rowc\">\n<div class=\"kchip\">🚧 taints<small> node pushes away</small></div>\n<span class=\"harr\">⇄</span>\n<div class=\"kchip\">🧲 affinity<small> pod pulls toward</small></div>\n<span class=\"harr\">⇄</span>\n<div class=\"kchip\">⚖️ spread<small> distribution discipline</small></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Direction matters — the classic confusion:</b> taints are <b>node-side repulsion</b> (the node refuses visitors without keys). Affinity is <b>pod-side attraction</b> (the Pod states its preferences). They never do each other's job — taints can't attract, affinity can't evict.</div></div>\n<div class=\"grid3\">\n<div class=\"card center\"><div>🗄️</div><p><b>Dedicate nodes</b><br />GPU / memory-huge<br />→ taints + tolerations</p></div>\n<div class=\"card center\"><div>📍</div><p><b>Pin to hardware</b><br />SSD, region, zone<br />→ node affinity</p></div>\n<div class=\"card center\"><div>🕸️</div><p><b>Resilience layout</b><br />HA across zones<br />→ spread + anti-affinity</p></div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Decision shortcut:</b> keeping things <b>OFF</b> nodes → taints. Getting things <b>ON</b> specific nodes → node affinity. Relationships <b>between Pods</b> → pod affinity/anti-affinity. <b>Evenness</b> → spread. The rest of the book is these four, in depth.</div></div>\n<p>⏭️ Part II opens with the repulsion side — <a href=\"#ch03\">CH 03: Taints — Effects &amp; Use Cases</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch01\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch03\">next ▶</a></span><span>Page 4</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 03</span><h2 id=\"taints-effects-amp-use-cases\">🚧 Taints — Effects &amp; Use Cases</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A taint is a <b>node-side repulsion field</b>: <code>key=value:effect</code>. Book 01's Lab 5 proved the mechanics — this page is the full strategic picture.</p>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl taint node node1 <span class=\"c\">gpu=nvidia</span>:<span class=\"y\">NoSchedule</span>\nnode/node1 tainted\n<span class=\"p\">$</span> kubectl taint node node1 <span class=\"c\">gpu=nvidia</span>:NoSchedule-<span class=\"g\">  # trailing dash = remove</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Effect</th><th>Running Pods</th><th>New Pods</th><th>Use case</th></tr>\n<tr><td><span class=\"stbadge st-run\">NoSchedule</span></td><td>stay</td><td>blocked unless tolerated</td><td>dedicate nodes (GPU, SSD, prod-only)</td></tr>\n<tr><td><span class=\"stbadge st-pend\">PreferNoSchedule</span></td><td>stay</td><td>avoided if alternatives exist</td><td>soft segregation — \"try not to\"</td></tr>\n<tr><td><span class=\"stbadge st-term\">NoExecute</span></td><td><b>EVICTED</b> now</td><td>blocked unless tolerated</td><td>remove workloads when a node degrades</td></tr>\n</table></div>\n<h3 id=\"the-three-strategic-uses\">🎯 The three strategic uses</h3>\n<div class=\"grid3\">\n<div class=\"card\"><p><b>1 · Dedication</b><br /><code>dedicated=ml:NoSchedule</code> — only ML team's Pods (which tolerate) may land. A reservation <i>without</i> reserving capacity.</p></div>\n<div class=\"card\"><p><b>2 · Special hardware</b><br /><code>gpu=nvidia:NoSchedule</code> — prevents accidental placement of Pods that can't use the GPU… and of Pods that would <i>waste</i> it.</p></div>\n<div class=\"card\"><p><b>3 · Node condition → eviction</b><br />The control plane itself taints sick nodes with <b>NoExecute</b> — workloads flee a dying node automatically (CH 05).</p></div>\n</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Two traps:</b> (1) taints don't <b>attract</b> — a tolerated Pod <i>may</i> land elsewhere; to pin it, combine taints with <b>node affinity</b> (CH 06). (2) <b>NoExecute is a weapon</b> — adding one manually evicts production Pods mid-flight. Book 01 · Lab 5's trick question (taint <i>after</i> Pod exists) is this effect in action.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> taints come in three strengths — <i>block new (NoSchedule), gently avoid (PreferNoSchedule), or evict existing (NoExecute)</i> — and their job description is \"keep the wrong workloads off this node.\"</div></div>\n<p>⏭️ The key side of the lock — <a href=\"#ch04\">CH 04: Tolerations</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch02\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch04\">next ▶</a></span><span>Page 5</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 04</span><h2 id=\"tolerations-operators-amp-tolerationseconds\">🔑 Tolerations — Operators &amp; tolerationSeconds</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A toleration is a <b>Pod-side permission</b>: \"I may land on (or survive on) nodes carrying this taint.\" Match rule: <b>key + operator (+ value) + effect</b>.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">tolerations</span>:\n  - <span class=\"c\">key</span>: gpu\n    <span class=\"c\">operator</span>: <span class=\"y\">Equal</span>          <span class=\"g\"># default — value must match exactly</span>\n    <span class=\"c\">value</span>: nvidia\n    <span class=\"c\">effect</span>: NoSchedule\n  - <span class=\"c\">key</span>: <span class=\"m\">\"dedicated\"</span>\n    <span class=\"c\">operator</span>: <span class=\"y\">Exists</span>        <span class=\"g\"># ANY value, as long as key exists</span>\n    <span class=\"c\">effect</span>: NoSchedule\n  - <span class=\"c\">key</span>: <span class=\"m\">\"\"</span>\n    <span class=\"c\">operator</span>: <span class=\"y\">Exists</span>\n    <span class=\"c\">effect</span>: <span class=\"m\">\"\"</span>              <span class=\"g\"># tolerate EVERYTHING (use with fear)</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Operator</th><th>Matches</th><th>Value field</th></tr>\n<tr><td><code>Equal</code> <span class=\"stbadge st-comp\">default</span></td><td>key exists <b>and</b> value is identical</td><td>required</td></tr>\n<tr><td><code>Exists</code></td><td>key exists, any value (wildcard)</td><td>must be <b>empty</b></td></tr>\n</table></div>\n<h3 id=\"tolerationseconds-the-grace-timer-noexecute-only\">⏱️ tolerationSeconds — the grace timer (NoExecute only)</h3>\n<div class=\"term\"><span class=\"c\">tolerations</span>:\n- <span class=\"c\">key</span>: node.kubernetes.io/not-ready\n  <span class=\"c\">operator</span>: <span class=\"y\">Exists</span>\n  <span class=\"c\">effect</span>: NoExecute\n  <span class=\"c\">tolerationSeconds</span>: <span class=\"y\">300</span>   <span class=\"g\"># if the taint lasts &gt; 5 min → THEN evict me</span></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>The resilience dial:</b> a transient blip (&lt; 5 min) → your Pod rides it out. A real outage → eviction after the grace period. This is <i>exactly</i> how the default tolerations on Deployments behave — it's why brief node hiccups don't mass-evict your fleet.</div></div>\n<ul>\n<li>🚫 No <code>tolerationSeconds</code> + NoExecute tolerated = <b>survive forever</b> on the tainted node</li>\n<li>🧩 Effect matching is literal: a toleration for <code>NoSchedule</code> does nothing against <code>NoExecute</code> on the same key</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> tolerations are the <b>only</b> way past a taint — <code>Equal</code> for exact locks, <code>Exists</code> for skeleton keys, and <code>tolerationSeconds</code> turns a hard eviction into a grace period.</div></div>\n<p>⏭️ The taints you didn't create — <a href=\"#ch05\">CH 05: Well-Known Taints</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch03\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch05\">next ▶</a></span><span>Page 6</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 05</span><h2 id=\"well-known-taints-the-cluster-s-own\">🏥 Well-Known Taints — The Cluster's Own</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The node-lifecycle controller and kubelet <b>taint nodes automatically</b> as conditions change. These aren't your taints — they're the cluster's immune response, and recognizing them is a diagnostic superpower.</p>\n<div class=\"table-scroll\"><table>\n<tr><th>Taint</th><th>Effect</th><th>Meaning</th></tr>\n<tr><td><code>node.kubernetes.io/not-ready</code></td><td>NoSchedule/NoExecute</td><td>node's Ready condition = False (kubelet heartbeat lost)</td></tr>\n<tr><td><code>node.kubernetes.io/unreachable</code></td><td>NoExecute/NoSchedule</td><td>node unreachable (network partition) — later becomes not-ready</td></tr>\n<tr><td><code>node.kubernetes.io/disk-pressure</code></td><td>NoSchedule</td><td>disk running out — no NEW pods (existing keep running)</td></tr>\n<tr><td><code>node.kubernetes.io/memory-pressure</code></td><td>NoSchedule</td><td>memory scarcity on the node</td></tr>\n<tr><td><code>node.kubernetes.io/network-unavailable</code></td><td>NoSchedule</td><td>networking not configured yet (some clouds)</td></tr>\n<tr><td><code>node.kubernetes.io/unschedulable</code></td><td>NoSchedule</td><td>added by <code>kubectl cordon</code> — CH 10</td></tr>\n<tr><td><code>node-role.kubernetes.io/control-plane</code></td><td>NoSchedule</td><td>the brain-protection taint (Book 01 · CH 07)</td></tr>\n</table></div>\n<div class=\"mtree\"><b>Node degrades</b> <span class=\"g\">→</span> <u>NotReady / Unreachable</u> <span class=\"g\">NoExecute taint applied</span>\n      │\n      ├─ pods <b>without</b> toleration → evicted <span class=\"g\">(grace per tolerationSeconds)</span>\n      ├─ deployments recreate them on healthy nodes <span class=\"g\">← Book 01 · CH 06 loop</span>\n      └─ node recovers → taint removed → schedulable again</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Debug move:</b> mysterious Pending + \"node(s) had untolerated taint\" in events (Book 01 · CH 23)? Run <code>kubectl describe node N | grep Taints</code> — the taint list <i>is</i> the diagnosis. <code>disk-pressure</code> appearing on nodes is also your cue for storage cleanup (Book 05's territory).</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> the cluster self-medicates with taints — <i>sick nodes get NoExecute'd, workloads evacuate, healthy nodes absorb the load</i> — and self-healing \"magic\" from Book 01 is really this mechanism plus reconciliation.</div></div>\n<p>⏭️ Part III: now the Pod speaks — <a href=\"#ch06\">CH 06: Node Affinity</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch04\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch06\">next ▶</a></span><span>Page 7</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 06</span><h2 id=\"nodeselector-amp-node-affinity\">🧲 nodeSelector &amp; Node Affinity</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Pod-side attraction to specific nodes. <code>nodeSelector</code> is the simple ancestor; <b>node affinity</b> adds operators, weights, and soft preferences.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">nodeSelector</span>:              <span class=\"g\"># the simple form: hard, exact-match only</span>\n    disk: ssd\n  <span class=\"c\">affinity</span>:\n    <span class=\"c\">nodeAffinity</span>:\n      <span class=\"c\">requiredDuringSchedulingIgnoredDuringExecution</span>:   <span class=\"g\"># HARD (filter)</span>\n        <span class=\"c\">nodeSelectorTerms</span>:\n        - <span class=\"c\">matchExpressions</span>:\n          - { <span class=\"c\">key</span>: disk, <span class=\"c\">operator</span>: <span class=\"y\">In</span>, <span class=\"c\">values</span>: [<span class=\"m\">ssd</span>, <span class=\"m\">nvme</span>] }\n      <span class=\"c\">preferredDuringSchedulingIgnoredDuringExecution</span>:  <span class=\"g\"># SOFT (score)</span>\n      - <span class=\"c\">weight</span>: <span class=\"y\">80</span>            <span class=\"g\"># 1–100 — a vote, not a veto</span>\n        <span class=\"c\">preference</span>:\n          <span class=\"c\">matchExpressions</span>:\n          - { <span class=\"c\">key</span>: zone, <span class=\"c\">operator</span>: <span class=\"y\">In</span>, <span class=\"c\">values</span>: [<span class=\"m\">east</span>] }</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Operators</th><th>Meaning</th></tr>\n<tr><td><code>In</code> · <code>NotIn</code></td><td>value is / is not in the list</td></tr>\n<tr><td><code>Exists</code> · <code>DoesNotExist</code></td><td>key present / absent (any value)</td></tr>\n<tr><td><code>Gt</code> · <code>Lt</code></td><td>numeric greater/less than (node labels as numbers)</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Decode the long names — they're the whole contract:</b> <code>required…</code> = filter (no match → Pending). <code>preferred…</code> = score (hint). <b>IgnoredDuringExecution</b> = if the node's labels <i>change after</i> your Pod is running, the Pod <b>stays</b> — affinity is checked at scheduling time only. (The mirror concept <code>RequiredDuringExecution</code> exists for pod affinity — live re-evaluation.)</div></div>\n<div class=\"rowc\">\n<div class=\"kchip\">label node: <code>kubectl label node n1 disk=ssd</code></div>\n<span class=\"harr\">→</span>\n<div class=\"kchip\">Pod with <code>disk In [ssd]</code></div>\n<span class=\"harr\">→</span>\n<div class=\"kchip\">lands only there</div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> node affinity = nodeSelector with superpowers — <b>operators for matching, weights for preferences, and \"IgnoredDuringExecution\" meaning the lock is checked once, at scheduling time</b>. Lab 1 proves the hard/soft split live.</div></div>\n<p>⏭️ Affinity between Pods — <a href=\"#ch07\">CH 07: Pod Affinity &amp; Anti-Affinity</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch05\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch07\">next ▶</a></span><span>Page 8</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 07</span><h2 id=\"pod-affinity-amp-anti-affinity\">👥 Pod Affinity &amp; Anti-Affinity</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Node affinity asks \"which <i>nodes</i>?\" — pod affinity asks \"near which <i>other Pods</i>?\", measured through a <b>topology domain</b> (same node? same zone? same region?).</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">affinity</span>:\n    <span class=\"c\">podAffinity</span>:             <span class=\"g\"># CO-LOCATE — \"keep me near my cache\"</span>\n      <span class=\"c\">requiredDuringSchedulingIgnoredDuringExecution</span>:\n      - <span class=\"c\">topologyKey</span>: <span class=\"y\">kubernetes.io/hostname</span>   <span class=\"g\"># same NODE</span>\n        <span class=\"c\">labelSelector</span>:\n          <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: cache }\n    <span class=\"c\">podAntiAffinity</span>:         <span class=\"g\"># SEPARATE — \"never put replicas together\"</span>\n      <span class=\"c\">preferredDuringSchedulingIgnoredDuringExecution</span>:\n      - <span class=\"c\">weight</span>: <span class=\"y\">100</span>\n        <span class=\"c\">podAffinityTerm</span>:\n          <span class=\"c\">topologyKey</span>: <span class=\"y\">topology.kubernetes.io/zone</span>  <span class=\"g\"># different ZONES</span>\n          <span class=\"c\">labelSelector</span>:\n            <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: web }</div>\n<div class=\"table-scroll\"><table>\n<tr><th>topologyKey (common)</th><th>Domain = \"together means…\"</th></tr>\n<tr><td><code>kubernetes.io/hostname</code></td><td>same physical node</td></tr>\n<tr><td><code>topology.kubernetes.io/zone</code></td><td>same availability zone</td></tr>\n<tr><td><code>topology.kubernetes.io/region</code></td><td>same region</td></tr>\n</table></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">✅ Affinity (co-locate)</div>\n<p><b>web + its cache</b> on one node → localhost-fast calls, one bill. <b>Latency-sensitive pairs</b> that talk constantly.</p></div>\n<div class=\"card\"><div class=\"zlabel\">✅ Anti-affinity (separate)</div>\n<p><b>3 replicas of web</b> on 3 zones → one zone dies, 2/3 survive. <b>Never stack the blast radius.</b></p></div>\n</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>required anti-affinity is a placement cliff:</b> more replicas than topology domains → the extras sit <b>Pending forever</b> (3 replicas, 1 node = 1 runs, 2 Pending — Lab 2 proves it). Production default: <b>preferred + weight 100</b>, or better — topologySpread (CH 08).</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> pod (anti-)affinity = relationship rules between Pods, expressed as \"same/different <i>topology domain</i>\" — powerful for latency and HA, but <code>required</code> versions trade flexibility for guarantees.</div></div>\n<p>⏭️ The modern alternative — <a href=\"#ch08\">CH 08: topologySpreadConstraints</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch06\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch08\">next ▶</a></span><span>Page 9</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 08</span><h2 id=\"topologyspreadconstraints\">⚖️ topologySpreadConstraints</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Anti-affinity answers \"are any Pods here?\" — spread answers a better question: <b>\"is the distribution <i>even</i>?\"</b> One constraint replaces a pile of weights.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">topologySpreadConstraints</span>:\n  - <span class=\"c\">maxSkew</span>: <span class=\"y\">1</span>                       <span class=\"g\"># max allowed imbalance</span>\n    <span class=\"c\">topologyKey</span>: <span class=\"y\">topology.kubernetes.io/zone</span>\n    <span class=\"c\">whenUnsatisfiable</span>: <span class=\"y\">DoNotSchedule</span>  <span class=\"g\"># or: ScheduleAnyway (soft)</span>\n    <span class=\"c\">labelSelector</span>:\n      <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: web }\n  <span class=\"g\"># — maxSkew = (most pods in one domain) − (fewest)\n  # — domains with ZERO pods count too (they pull new pods!)</span></div>\n<div class=\"zone zone-net\">\n<div class=\"zlabel\">maxSkew: 1 in action — 6 replicas, 3 zones</div>\n<div class=\"rowc\">\n<div class=\"nb c-emerald\">zone-a<small>2 🫛🫛</small></div>\n<div class=\"nb c-emerald\">zone-b<small>2 🫛🫛</small></div>\n<div class=\"nb c-emerald\">zone-c<small>2 🫛🫛</small></div>\n</div>\n<p>2−2−2 → skew 0 ✅  ·  3−2−1 → skew 2 ❌ next Pod forced to zone-c  ·  3−3−0 → skew 3, but 0-domain \"pulls\" until fed</p>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th>whenUnsatisfiable</th><th>Behavior when the rule can't hold</th></tr>\n<tr><td><code>DoNotSchedule</code></td><td>hard — Pod waits (Pending) until it can comply</td></tr>\n<tr><td><code>ScheduleAnyway</code></td><td>soft — place anyway, but the score penalty steers future Pods</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Spread vs anti-affinity — when which?</b> Anti-affinity: <i>boolean</i> togetherness, per-Pod-pair relationships, cheap on small sets. Spread: <i>numeric</i> evenness across N domains, scales to hundreds of replicas, and — the killer feature — counts <b>empty domains</b>, so a fresh zone always receives traffic first.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> topologySpreadConstraints = \"keep skew ≤ maxSkew across this topology\" — the modern, scalable answer to \"spread my replicas,\" with a hard mode (<code>DoNotSchedule</code>) and a soft mode (<code>ScheduleAnyway</code>).</div></div>\n<p>⏭️ When scarcity gets violent — <a href=\"#ch09\">CH 09: Priority &amp; Preemption</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch07\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch09\">next ▶</a></span><span>Page 10</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 09</span><h2 id=\"priority-classes-amp-preemption\">👑 Priority Classes &amp; Preemption</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>When nothing fits anywhere, a high-priority Pod may <b>evict lower-priority Pods</b> to make room. Priority is the cluster's pecking order under scarcity.</p>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: scheduling.k8s.io/v1\n<span class=\"c\">kind</span>: PriorityClass\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: high-priority }\n<span class=\"c\">value</span>: <span class=\"y\">1000000</span>              <span class=\"g\"># higher = more important</span>\n<span class=\"c\">globalDefault</span>: <span class=\"y\">false</span>        <span class=\"g\"># one class MAY be the default</span>\n<span class=\"c\">preemptionPolicy</span>: <span class=\"y\">PreemptLowerPriority</span>  <span class=\"g\"># default; or Never</span></div>\n<div class=\"term mini\"><span class=\"c\">spec</span>:\n  <span class=\"c\">priorityClassName</span>: high-priority   <span class=\"g\"># attach to the Pod</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Built-in class</th><th>Value</th><th>Reserved for</th></tr>\n<tr><td><code>system-node-critical</code></td><td>2,000,001,000</td><td>kubelet-essential: CNI, kube-proxy</td></tr>\n<tr><td><code>system-cluster-critical</code></td><td>2,000,000,000</td><td>CoreDNS, metrics — cluster functions</td></tr>\n<tr><td><i>your Pods (no class)</i></td><td>0</td><td>everything below the system floor</td></tr>\n</table></div>\n<h3 id=\"how-preemption-actually-fires\">🗡️ How preemption actually fires</h3>\n<div class=\"mtree\"><b>High-prio Pod → Pending</b> <span class=\"g\">(no node fits — filter fails on resources)</span>\n      │ scheduler tries placement\n      ▼\n<u>Preemption attempt</u>: find node where evicting <b>lower-prio</b> victims\n   would free enough for the whole Pod (incl. its requests!)\n      ▼\nvictims deleted gracefully <span class=\"g\">(their owners recreate them — elsewhere, later)</span>\n      ▼\nhigh-prio Pod scheduled into the gap ✅</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Two honesty notes:</b> (1) preemption is <b>resource-arithmetic, not revenge</b> — the scheduler only kills the <i>minimum set</i> of lowest-priority victims, and only when the high-prio Pod genuinely can't fit. (2) Your Pods' priority also decides <b>kubelet eviction order</b> under node pressure — layered on top of QoS from Book 02 · CH 15.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> PriorityClass = a number that means \"in a shortage, I eat first\" — driving both <b>preemption at scheduling time</b> and <b>eviction order at runtime</b>. Lab 3 watches a real preemption.</div></div>\n<p>⏭️ Part V: now <i>you</i> touch the nodes — <a href=\"#ch10\">CH 10: Cordon, Drain &amp; Uncordon</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch08\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch10\">next ▶</a></span><span>Page 11</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 10</span><h2 id=\"cordon-drain-amp-uncordon\">🛠️ Cordon, Drain &amp; Uncordon</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Node maintenance (kernel upgrades, hardware swaps) without downtime = a three-verb dance. <b>Cordon</b> stops new arrivals; <b>drain</b> evacuates; <b>uncordon</b> reopens.</p>\n<div class=\"term\"><span class=\"p\">$</span> kubectl cordon node1           <span class=\"g\"># 1 · add unschedulable taint (CH 05)</span>\nnode/node1 cordoned\n<span class=\"p\">$</span> kubectl drain node1 <span class=\"y\">--ignore-daemonsets</span> <span class=\"y\">--delete-emptydir-data</span>\nnode/node1 cordoned                    <span class=\"g\"># drain cordons for you too</span>\nevicting pod shop/web-7d9f             <span class=\"g\"># graceful eviction — PDB-aware!</span>\npod/web-7d9f evicted\n<span class=\"p\">$</span> # …do the maintenance…\n<span class=\"p\">$</span> kubectl uncordon node1        <span class=\"g\"># 3 · reopen</span>\nnode/node1 uncordoned</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Flag</th><th>Why it exists</th></tr>\n<tr><td><code>--ignore-daemonsets</code></td><td>DaemonSet Pods are node-bound by design (log agents, CNI) — drain <b>skips</b> them; without the flag drain aborts</td></tr>\n<tr><td><code>--delete-emptydir-data</code></td><td>Pods with <code>emptyDir</code> lose data on eviction — drain refuses by default; the flag says \"ephemeral, go ahead\"</td></tr>\n<tr><td><code>--force</code></td><td>evict Pods <b>not managed by a controller</b> (standalone Pods die with no replacement — you were warned, Book 01 · CH 15)</td></tr>\n<tr><td><code>--grace-period / --timeout</code></td><td>tune eviction grace; PDBs can block indefinitely → drain waits/times out</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Drain respects PodDisruptionBudgets (PDBs)</b> — \"keep ≥ 2 web replicas alive\" pauses drain until it can evict safely. Production rule: <i>define PDBs before your first real drain</i>, or the \"safety\" is zero. (Also: cordon ≠ drain — cordon alone just stops <i>new</i> placements.)</div></div>\n<div class=\"road\">\n<div class=\"step\"><span class=\"stepnum\">1</span><span><b>cordon</b> — no NEW Pods land (existing keep running)</span></div>\n<div class=\"step\"><span class=\"stepnum\">2</span><span><b>drain</b> — evict everything the controllers can recreate, PDB-respecting</span></div>\n<div class=\"step\"><span class=\"stepnum\">3</span><span><b>maintain</b> — patch, reboot, swap hardware</span></div>\n<div class=\"step\"><span class=\"stepnum\">4</span><span><b>uncordon</b> — taint removed; Scheduler refills the node</span></div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> maintenance = <i>cordon (close the door) → drain (empty the room, politely) → uncordon (reopen)</i> — and the two flags you'll type forever are <code>--ignore-daemonsets</code> and <code>--delete-emptydir-data</code>. Lab 4 runs the full cycle.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch09\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch11\">next ▶</a></span><span>Page 12</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 11</span><h2 id=\"static-pods\">🪨 Static Pods</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<p>Static Pods are created and managed <b>directly by the kubelet</b>, from manifest files on the node's disk — no Deployment, no Scheduler, no controller. The Scheduler's total bypass.</p>\n<div class=\"mtree\">kubelet flags: <u>--pod-manifest-path=/etc/kubernetes/manifests</u>\n      │ watches the dir (default on kubeadm)\n      ▼\n<b>file appears</b> → kubelet runs the Pod      <span class=\"g\">no API call needed</span>\n<b>file edited</b>  → Pod updated               <span class=\"g\">file IS the spec</span>\n<b>file deleted</b> → Pod dies\n<b>kubectl delete</b> → Pod briefly dies → <b>kubelet recreates it</b> <span class=\"r\">(undeletable!)</span></div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get pods -n kube-system\n<span class=\"y\">NAME                            READY  STATUS</span>\netcd-minikube                  1/1    Running  <span class=\"g\"># ← static!</span>\nkube-apiserver-minikube        1/1    Running  <span class=\"g\"># ← static!</span>\nkube-controller-manager-minikube 1/1   Running  <span class=\"g\"># ← static!</span>\nkube-scheduler-minikube        1/1    Running  <span class=\"g\"># ← static!</span>\ncoredns-7db6d8ff4b-abcde       1/1    Running  <span class=\"g\"># ← Deployment</span></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>The bootstrap paradox, solved:</b> the Control Plane runs as static Pods because <i>something must run the API Server before the API Server exists</i>. The kubelet + a folder of YAML boot the entire brain — chicken, meet egg. (The <code>-minikube</code> / <code>-nodename</code> suffix: kubelet also creates a read-only <b>mirror Pod</b> in the API so you can <code>kubectl get</code> them.)</div></div>\n<ul>\n<li>🧪 Your own static Pod: drop a valid Pod manifest into the manifest dir → running within seconds, Scheduler never involved</li>\n<li>🚧 They ignore taints, affinity, and drain-eviction logic (the file rules) — that's why <code>drain --ignore-daemonsets</code> and static/mirror pods go together</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> static Pods are <b>kubelet-and-disk only</b> — the mechanism that boots the control plane itself, undeletable through kubectl because the source of truth is a file on the node.</div></div>\n<p>⏭️ Prove all of it with your hands — <a href=\"#lab1\">Part VI: Labs</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch10\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab1\">labs ▶</a></span><span>Page 13</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 1</span><h2 id=\"node-affinity-required-vs-preferred\">🔬 Node Affinity — Required vs Preferred</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Label the node + hard affinity</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl label node minikube disk=ssd\n<span class=\"p\">$</span> kubectl create deploy aff --image=nginx --replicas=2\n<span class=\"p\">$</span> kubectl patch deploy aff <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> <span class=\"m\">'{\"spec\":{\"template\":{\"spec\":{\n  \"affinity\":{\"nodeAffinity\":{\"requiredDuringSchedulingIgnoredDuringExecution\":\n  {\"nodeSelectorTerms\":[{\"matchExpressions\":[{\"key\":\"disk\",\"operator\":\"In\",\n  \"values\":[\"ssd\"]}]}]}}}}}}}'</span>\n<span class=\"p\">$</span> kubectl get pods -o wide  <span class=\"g\"># all on minikube ✓ (label matches)</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · Break the label — watch required bite</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl label node minikube disk-\n<span class=\"p\">$</span> kubectl scale deploy aff --replicas=<span class=\"y\">3</span>\n<span class=\"p\">$</span> kubectl get pods\n<span class=\"y\">aff-xxx   1/1  Running</span>   <span class=\"g\"># old pods: IgnoredDuringExecution — STAY</span>\n<span class=\"r\">aff-yyy   0/1  Pending</span>   <span class=\"g\"># new pod: no node matches → filter fails</span>\n<span class=\"p\">$</span> kubectl describe pod -l app=aff | <span class=\"c\">grep</span> -A2 Events | <span class=\"c\">tail</span> -2\n<span class=\"r\">0/1 nodes are available: 1 node(s) didn't match … affinity</span></div></div>\n<div class=\"labstep\"><div>STEP 3 · Switch to preferred — same break, different outcome</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl delete deploy aff &amp;&amp; kubectl create deploy soft --image=nginx --replicas=2\n<span class=\"p\">$</span> kubectl patch deploy soft <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> <span class=\"m\">'{\"spec\":{\"template\":{\"spec\":{\n  \"affinity\":{\"nodeAffinity\":{\"preferredDuringSchedulingIgnoredDuringExecution\":\n  [{\"weight\":80,\"preference\":{\"matchExpressions\":[{\"key\":\"disk\",\"operator\":\"In\",\n  \"values\":[\"ssd\"]}]}}]}}}}}}'</span>\n<span class=\"p\">$</span> kubectl scale deploy soft --replicas=3  <span class=\"g\"># label still gone…</span>\n<span class=\"p\">$</span> kubectl get pods  <span class=\"g\"># 3/3 Running — preferred only VOTES, never vetoes</span></div></div>\n<p><b>Proved:</b> required = filter (Pending on mismatch), preferred = score (never blocks), <b>IgnoredDuringExecution</b> = running Pods stay. <b>Teardown:</b> <code>kubectl delete deploy soft</code>.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#ch11\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab2\">next ▶</a></span><span>Page 14</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 2</span><h2 id=\"anti-affinity-prove-the-separation\">🔬 Anti-Affinity — Prove the Separation</h2><span class=\"dbadge\">🟠 10 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Required anti-affinity on a ONE-node cluster</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create deploy sep --image=nginx --replicas=3\n<span class=\"p\">$</span> kubectl patch deploy sep <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> <span class=\"m\">'{\"spec\":{\"template\":{\"spec\":{\n  \"affinity\":{\"podAntiAffinity\":{\"requiredDuringSchedulingIgnoredDuringExecution\":\n  [{\"topologyKey\":\"kubernetes.io/hostname\",\n    \"labelSelector\":{\"matchLabels\":{\"app\":\"sep\"}}}]}}}}}}'</span>\n<span class=\"p\">$</span> kubectl get pods\n<span class=\"y\">sep-aaa   1/1  Running</span>  <span class=\"g\"># fits — node is empty of \"sep\"</span>\n<span class=\"r\">sep-bbb   0/1  Pending</span>  <span class=\"g\"># node already has one!</span>\n<span class=\"r\">sep-ccc   0/1  Pending</span>  <span class=\"g\"># same hostname domain — no second one exists</span></div></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 WHY (events)</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl describe pod sep-bbb | <span class=\"c\">tail</span> -2\n<span class=\"r\">0/1 nodes are available:\n1 node(s) didn't match pod\nanti-affinity rules.</span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">🔍 THE LESSON</div><div class=\"tabbody\"><span class=\"g\"># required anti-affinity:\n# replicas &gt; topology\n# domains = permanent\n# Pending. 3 replicas\n# × 1 node = 2 orphans.</span></div></div>\n</div>\n<div class=\"labstep\"><div>STEP 2 · Soften it — everyone fits</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl patch deploy sep <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> <span class=\"m\">'{\"spec\":{\"template\":{\"spec\":{\n  \"affinity\":{\"podAntiAffinity\":{\"preferredDuringSchedulingIgnoredDuringExecution\":\n  [{\"weight\":100,\"podAffinityTerm\":{\"topologyKey\":\"kubernetes.io/hostname\",\n    \"labelSelector\":{\"matchLabels\":{\"app\":\"sep\"}}}}]}}}}}}'</span>\n<span class=\"p\">$</span> kubectl get pods  <span class=\"g\"># 3/3 Running — co-located, but only because we must</span></div></div>\n<p><b>Proved:</b> topology domains are finite; <code>required</code> anti-affinity hard-caps your replica count per domain. <b>Teardown:</b> <code>kubectl delete deploy sep</code>.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#lab1\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab3\">next ▶</a></span><span>Page 15</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 3</span><h2 id=\"priority-amp-preemption-live\">🔬 Priority &amp; Preemption Live</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Setup note:</b> preemption needs <b>resource pressure</b>. We fill the node with low-priority Pods holding real memory requests, then ask for a big high-priority Pod. Adjust sizes to your cluster's free memory.</div></div>\n<div class=\"labstep\"><div>STEP 1 · Two classes + a filled floor</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl create priorityclass low  <span class=\"y\">--value</span>=100\n<span class=\"p\">$</span> kubectl create priorityclass high <span class=\"y\">--value</span>=1000\n<span class=\"p\">$</span> kubectl create deploy filler --image=polinux/stress --replicas=6 \\\n  -- stress --vm 1 --vm-bytes 10M --timeout 6000s\n<span class=\"p\">$</span> kubectl set resources deploy/filler <span class=\"y\">--requests</span>=memory=<span class=\"y\">500Mi</span>\n<span class=\"p\">$</span> kubectl patch deploy filler <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> \\\n  <span class=\"m\">'{\"spec\":{\"template\":{\"spec\":{\"priorityClassName\":\"low\"}}}}'</span>\n<span class=\"p\">$</span> kubectl get pods -l app=filler  <span class=\"g\"># 6 Running — floor is loaded</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · The VIP arrives — preemption fires</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl run vip --image=polinux/stress --restart=Never \\\n  --overrides=<span class=\"m\">'{\"spec\":{\"priorityClassName\":\"high\",\"containers\":[{\"name\":\"s\",\n  \"image\":\"polinux/stress\",\"args\":[\"--vm\",\"1\",\"--vm-bytes\",\"50M\"],\n  \"resources\":{\"requests\":{\"memory\":\"1500Mi\"}}}]}}'</span> -- stress --vm 1 --vm-bytes 50M\n<span class=\"p\">$</span> kubectl get pods -w\n<span class=\"y\">filler-xxx   Terminating</span>  <span class=\"g\"># ← a low-prio VICTIM was chosen</span>\n<span class=\"p\">vip          Running</span>      <span class=\"g\"># ← took its place</span></div></div>\n<div class=\"labstep\"><div>STEP 3 · Read the verdict</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get events | <span class=\"c\">grep</span> -i preempt\n<span class=\"g\">Preempted by pod default/vip … to make room</span>\n<span class=\"p\">$</span> kubectl get events | <span class=\"c\">grep</span> vip | <span class=\"c\">head</span> -3\n<span class=\"y\">Successfully assigned … node minikube</span></div></div>\n<p><b>Proved:</b> scarcity + priority = eviction of the weak, <i>minimum victims only</i>. The filler Deployment recreates its Pod (Book 01 · CH 06) — everyone survives, the VIP just ate first. <b>Teardown:</b> <code>kubectl delete pod vip &amp;&amp; kubectl delete deploy filler &amp;&amp; kubectl delete pc low high</code>.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#lab2\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab4\">next ▶</a></span><span>Page 16</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 4</span><h2 id=\"the-maintenance-cycle\">🛠️ The Maintenance Cycle</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Cordon — close the door</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl cordon minikube\n<span class=\"p\">$</span> kubectl get nodes\n<span class=\"y\">NAME     STATUS              ROLES</span>\nminikube <span class=\"r\">Ready,SchedulingDisabled</span>  control-plane,master\n<span class=\"p\">$</span> kubectl describe node minikube | <span class=\"c\">grep</span> Taints\n<span class=\"r\">node.kubernetes.io/unschedulable:NoSchedule</span>  <span class=\"g\"># ← the cordon taint (CH 05!)</span>\n<span class=\"p\">$</span> kubectl scale deploy web --replicas=3  <span class=\"g\"># (any deployment)</span>\n<span class=\"p\">$</span> kubectl get pods -w  <span class=\"g\"># 3rd pod → Pending: nowhere to land</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · Drain — empty the room</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl drain minikube <span class=\"y\">--ignore-daemonsets</span> <span class=\"y\">--delete-emptydir-data</span>\nnode/minikube cordoned\n<span class=\"r\">evicting pod kube-system/coredns-…</span>\nevicting pod default/web-aaa\n<span class=\"g\">pod/web-aaa evicted</span>\n<span class=\"p\">$</span> kubectl get pods -A | <span class=\"c\">grep</span> -v Running\n<span class=\"g\"># (single-node cluster: evicted pods go Pending — they have\n#  nowhere else to go. on a 3-node cluster they'd REAPPEAR\n#  on the healthy nodes — Book 01 · CH 06 in action.)</span></div></div>\n<div class=\"labstep\"><div>STEP 3 · Uncordon — reopen</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl uncordon minikube\n<span class=\"p\">$</span> kubectl get nodes  <span class=\"g\"># Ready — SchedulingDisabled gone</span>\n<span class=\"p\">$</span> kubectl get pods -w  <span class=\"g\"># Pending pods schedule immediately 🎉</span></div></div>\n<p><b>Proved:</b> cordon = a NoSchedule taint you typed; drain = graceful, PDB-respecting evacuation; uncordon = instant refill. <b>Teardown:</b> scale your deployment back and delete leftovers.</p>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Muscle memory:</b> <code>drain node --ignore-daemonsets --delete-emptydir-data</code> — the two flags ride together on virtually every real maintenance run.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#lab3\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#quiz\">quiz ▶</a></span><span>Page 17</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">QUIZ</span><h2 id=\"self-check-quiz\">✅ Self-Check Quiz</h2><span class=\"dbadge\">☑ 10 questions</span></div>\n<div class=\"qz\"><span class=\"qn\">Q1.</span>The Scheduler processes a Pod in which order?<br /><b>A.</b> Score → Filter → Bind   <b>B.</b> Filter → Score → Bind   <b>C.</b> Bind → Filter → Score   <b>D.</b> Filter → Bind → Score</div>\n<div class=\"qz\"><span class=\"qn\">Q2.</span>Which taint effect evicts already-running Pods that don't tolerate it?<br /><b>A.</b> NoSchedule   <b>B.</b> PreferNoSchedule   <b>C.</b> NoExecute   <b>D.</b> None — taints never evict</div>\n<div class=\"qz\"><span class=\"qn\">Q3.</span><code>tolerationSeconds</code> applies to which effect?<br /><b>A.</b> NoExecute   <b>B.</b> NoSchedule   <b>C.</b> PreferNoSchedule   <b>D.</b> All three equally</div>\n<div class=\"qz\"><span class=\"qn\">Q4.</span>A Pod with <b>required</b> node affinity for <code>disk=ssd</code> is running. The node's label is removed. The Pod…<br /><b>A.</b> is evicted immediately   <b>B.</b> reschedules to another node   <b>C.</b> crashes   <b>D.</b> keeps running — IgnoredDuringExecution</div>\n<div class=\"qz\"><span class=\"qn\">Q5.</span><b>required</b> pod anti-affinity on <code>kubernetes.io/hostname</code>, 3 replicas, a 1-node cluster:<br /><b>A.</b> all 3 co-located   <b>B.</b> 1 Running, 2 Pending   <b>C.</b> the Deployment is rejected   <b>D.</b> round-robin placement</div>\n<div class=\"qz\"><span class=\"qn\">Q6.</span><code>maxSkew</code> in a topologySpreadConstraint defines…<br /><b>A.</b> minimum Pods per domain   <b>B.</b> number of allowed domains   <b>C.</b> max difference between the most- and least-loaded domains   <b>D.</b> the eviction threshold</div>\n<div class=\"qz\"><span class=\"qn\">Q7.</span>A high-priority Pod is Pending for lack of memory. The Scheduler…<br /><b>A.</b> may evict lower-priority Pods (minimum victims) to make room   <b>B.</b> waits until a node frees naturally   <b>C.</b> asks the kubelet to kill anything   <b>D.</b> reboots the busiest node</div>\n<div class=\"qz\"><span class=\"qn\">Q8.</span><code>kubectl drain</code> refuses to run without <code>--ignore-daemonsets</code> because…<br /><b>A.</b> DaemonSets restart too fast   <b>B.</b> drain cannot evict privileged Pods   <b>C.</b> kube-proxy blocks eviction   <b>D.</b> DaemonSet Pods are node-bound by design and would just be recreated — drain skips them</div>\n<div class=\"qz\"><span class=\"qn\">Q9.</span>Static Pods are…<br /><b>A.</b> Pods that never restart   <b>B.</b> created directly by the kubelet from a manifest directory — deleting via kubectl just gets them recreated   <b>C.</b> Pods without IP addresses   <b>D.</b> Deployments with replicas=1</div>\n<div class=\"qz\"><span class=\"qn\">Q10.</span>After <code>kubectl cordon node1</code>, the Pods already running on node1…<br /><b>A.</b> are evicted   <b>B.</b> are terminated   <b>C.</b> keep running; only NEW Pods avoid node1   <b>D.</b> migrate automatically</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#lab4\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#key\">answers ▶</a></span><span>Page 18</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">KEY</span><h2 id=\"answer-key-scoring\">🗝️ Answer Key + Scoring</h2><span class=\"dbadge\">grade yourself</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Q</th><th>Ans</th><th>Why — one line</th></tr>\n<tr><td>1</td><td><b>B</b></td><td>Filter (feasible) → Score (rank) → Bind — CH 01</td></tr>\n<tr><td>2</td><td><b>C</b></td><td>NoExecute evicts existing non-tolerating Pods now — CH 03</td></tr>\n<tr><td>3</td><td><b>A</b></td><td>The grace timer only makes sense for eviction — NoExecute — CH 04</td></tr>\n<tr><td>4</td><td><b>D</b></td><td>Affinity is scheduling-time only; label changes never evict — CH 06</td></tr>\n<tr><td>5</td><td><b>B</b></td><td>1 hostname domain &lt; 3 replicas → extras Pending forever — CH 07, Lab 2</td></tr>\n<tr><td>6</td><td><b>C</b></td><td>skew = max(domain count) − min(domain count), capped at maxSkew — CH 08</td></tr>\n<tr><td>7</td><td><b>A</b></td><td>Preemption = scheduler-driven, minimum-victim eviction — CH 09, Lab 3</td></tr>\n<tr><td>8</td><td><b>D</b></td><td>DaemonSet pods belong to their node; drain skips, flag acknowledges — CH 10</td></tr>\n<tr><td>9</td><td><b>B</b></td><td>kubelet + manifest dir = source of truth; API deletion is overridden — CH 11</td></tr>\n<tr><td>10</td><td><b>C</b></td><td>Cordon adds unschedulable taint — blocks placement, never evicts — CH 10, Lab 4</td></tr>\n</table></div>\n<div class=\"grid3\">\n<div class=\"card center\"><div>🏆</div><p><b>9–10</b><br />Ready for Book 05</p></div>\n<div class=\"card center\"><div>📖</div><p><b>6–8</b><br />Re-read missed chapters' 🔑 boxes</p></div>\n<div class=\"card center\"><div>🔁</div><p><b>&lt;6</b><br />Re-run Labs 1–4, then retake</p></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Missed Q4 or Q10?</b> They're the same fact wearing two hats: scheduling-time constraints never touch running Pods — only NoExecute taints and controller reconciliation do. Missed Q5? The topology-domain count is a hard ceiling for <code>required</code> anti-affinity.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#quiz\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#gloss\">next ▶</a></span><span>Page 19</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">GLOSS</span><h2 id=\"glossary\">📚 Glossary</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\n<div class=\"gl\"><b>Filter / Score / Bind</b> — the Scheduler's funnel: feasible → ranked → written to the Pod's nodeName.</div>\n<div class=\"gl\"><b>Taint</b> — node-side repulsion, <code>key=value:effect</code>; effects NoSchedule / PreferNoSchedule / NoExecute.</div>\n<div class=\"gl\"><b>Toleration</b> — Pod-side permission past a taint; operators Equal (exact) and Exists (wildcard, empty value).</div>\n<div class=\"gl\"><b>tolerationSeconds</b> — grace period before a NoExecute eviction takes effect.</div>\n<div class=\"gl\"><b>Well-known taints</b> — not-ready, unreachable, disk-pressure, memory-pressure, network-unavailable, unschedulable, control-plane — the cluster's automatic immune taints.</div>\n<div class=\"gl\"><b>nodeSelector</b> — simple hard label match on nodes.</div>\n<div class=\"gl\"><b>Node affinity</b> — required (filter) / preferred (score, weight 1–100) node matching with In/NotIn/Exists/DoesNotExist/Gt/Lt.</div>\n<div class=\"gl\"><b>IgnoredDuringExecution</b> — affinity evaluated at scheduling time only; later label changes never evict.</div>\n<div class=\"gl\"><b>Pod (anti-)affinity</b> — co-location / separation rules relative to other Pods, scoped by topologyKey.</div>\n<div class=\"gl\"><b>topologyKey</b> — the domain label defining \"together\": kubernetes.io/hostname, topology.kubernetes.io/zone|region.</div>\n<div class=\"gl\"><b>topologySpreadConstraints</b> — keep distribution even: maxSkew + topologyKey + whenUnsatisfiable (DoNotSchedule / ScheduleAnyway); empty domains attract.</div>\n<div class=\"gl\"><b>PriorityClass</b> — named integer priority; system-node-critical (2000001000) &gt; system-cluster-critical (2000000000) &gt; default 0.</div>\n<div class=\"gl\"><b>Preemption</b> — Scheduler evicts minimum lower-priority victims to place a higher-priority Pending Pod.</div>\n<div class=\"gl\"><b>Cordon</b> — mark node unschedulable (adds unschedulable:NoSchedule taint); no evictions.</div>\n<div class=\"gl\"><b>Drain</b> — cordon + graceful, PDB-respecting eviction of all recreatable Pods; --ignore-daemonsets / --delete-emptydir-data / --force.</div>\n<div class=\"gl\"><b>PodDisruptionBudget (PDB)</b> — \"keep ≥ N replicas during voluntary disruptions\"; drain waits for it.</div>\n<div class=\"gl\"><b>Static Pod</b> — kubelet-managed Pod from a node-local manifest directory (/etc/kubernetes/manifests); runs the control plane itself; undeletable via API.</div>\n<div class=\"gl\"><b>Mirror Pod</b> — the API-side read-only reflection kubelet creates so static Pods appear in kubectl.</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#key\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#cheat\">next ▶</a></span><span>Page 20</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CHEAT</span><h2 id=\"one-page-cheat-sheet\">📄 One-Page Cheat Sheet</h2><span class=\"dbadge\">🔵 print me</span></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">🚧 Taints &amp; tolerations</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl taint node N gpu=nvidia:NoSchedule\n<span class=\"p\">$</span> kubectl taint node N gpu=nvidia:NoExecute\n<span class=\"p\">$</span> kubectl taint node N gpu=nvidia:NoSchedule-<span class=\"g\"> # remove</span>\n<span class=\"c\">tolerations</span>:\n- {key: gpu, operator: Equal, value: nvidia, effect: NoSchedule}\n- {key: gpu, operator: Exists, effect: NoExecute,\n  tolerationSeconds: 300}\n<span class=\"g\">effects: block-new / prefer-avoid / evict-now</span></div></div>\n<div class=\"card\"><div class=\"zlabel\">🧲 Affinity &amp; spread</div><div class=\"term mini\"><span class=\"g\">node: required…/preferred…DuringScheduling\nIgnoredDuringExecution</span>\n<span class=\"g\">ops: In NotIn Exists DoesNotExist Gt Lt</span>\n<span class=\"g\">pod: podAffinity / podAntiAffinity + topologyKey\n  (hostname | zone | region)</span>\n<span class=\"c\">topologySpreadConstraints</span>:\n- {maxSkew: 1, topologyKey: zone,\n  whenUnsatisfiable: DoNotSchedule,\n  labelSelector: {matchLabels: {app: web}}}</div></div>\n</div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">👑 Priority</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl create priorityclass hi --value=1000\n<span class=\"c\">spec</span>: {priorityClassName: hi}\n<span class=\"g\">system-node-critical 2000001000\nsystem-cluster-critical 2000000000\ndefault pods: 0 · preemption = min victims\nalso drives kubelet eviction order (with QoS)</span></div></div>\n<div class=\"card\"><div class=\"zlabel\">🛠️ Maintenance</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl cordon N\n<span class=\"p\">$</span> kubectl drain N --ignore-daemonsets \\\n    --delete-emptydir-data [--force] [--timeout=…]\n<span class=\"g\"># evicts gracefully, respects PDBs\n# DaemonSet pods skipped</span>\n<span class=\"p\">$</span> kubectl uncordon N\n<span class=\"g\">static pods: /etc/kubernetes/manifests\n→ kubelet-born, API-undeletable</span></div></div>\n</div>\n<div class=\"card\"><div class=\"zlabel\">🧠 Facts worth a job offer</div>\n<ul>\n<li>Scheduling = Filter → Score → Bind; it happens ONCE — no re-evaluation of running Pods</li>\n<li>Taints repel (node-side), affinity attracts (pod-side) — they never do each other's job</li>\n<li>NoExecute = evict existing; tolerationSeconds = grace timer; Equal needs a value, Exists doesn't</li>\n<li>required anti-affinity caps replicas at topology-domain count; spread constraints scale better</li>\n<li>Preemption is minimum-victim arithmetic, not revenge; priority also orders kubelet evictions</li>\n<li>Drain = cordon + PDB-respecting eviction; DaemonSet pods are skipped, not evicted</li>\n<li>Static Pods bootstrap the control plane — the file on disk is the source of truth</li>\n</ul></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#gloss\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#finale\">finale ▶</a></span><span>Page 21</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">FINALE</span><h2 id=\"what-you-can-do-now\">🗺️ What You Can Do Now</h2><span class=\"dbadge\">🎓 Book 04 complete</span></div>\n<p>Book 01 built the machine, 02 dressed it, 03 connected it — Book 04 taught you <b>where everything is allowed to live, and how to move it safely</b>.</p>\n<div class=\"mtree\"><b>🎯 SCHEDULING — fully mapped:</b>\n├── <u>Funnel</u>        <span class=\"g\">filter (can) → score (should) → bind (done)</span>\n├── <u>Taints</u>        <span class=\"g\">NoSchedule · PreferNoSchedule · NoExecute</span>\n├── <u>Tolerations</u>   <span class=\"g\">Equal/Exists · tolerationSeconds</span>\n├── <u>Affinity</u>      <span class=\"g\">node + pod, required vs preferred, topologyKey</span>\n├── <u>Spread</u>        <span class=\"g\">maxSkew across zones — empty domains attract</span>\n├── <u>Priority</u>      <span class=\"g\">pecking order + preemption under scarcity</span>\n└── <u>Node ops</u>      <span class=\"g\">cordon → drain (PDB-aware) → uncordon · static pods</span></div>\n<h3 id=\"you-can-now\">✅ You can now…</h3>\n<ul>\n<li>Explain any Pending Pod: read the event, name the failing stage, name the knob that fixes it</li>\n<li>Dedicate nodes with taints + tolerations and pin workloads with affinity — without confusing the two directions</li>\n<li>Design replica layouts for HA (spread/anti-affinity) and know exactly when <code>required</code> becomes a Pending trap</li>\n<li>Set a priority hierarchy and predict who preempts whom under memory scarcity</li>\n<li>Run the full maintenance dance on a production node and describe what each flag protects</li>\n<li>Explain how the control plane boots itself with static Pods — and why you can't kubectl-delete them</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🎓</span><div><b>Where to next — Book 05 · Storage:</b> your Pods are placed perfectly — but <code>emptyDir</code> dies with the Pod (drain just taught you that the hard way). Book 05 gives data a life of its own: Volumes, PV/PVC, StorageClasses &amp; dynamic provisioning, access modes, reclaim policies, StatefulSets with stable storage, and CSI. Your databases finally get a home that survives everything.</div></div>\n<div class=\"center\">— End of Book 04 · 🎬 —</div>\n<div class=\"pgfoot\"><span>📘 Book 04 · Scheduling &amp; Node Management</span><span><a href=\"#cheat\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a></span><span>Page 22</span></div></div>\n\n\n","toc":[{"id":"scheduling-amp-node-management","text":"SCHEDULING &amp;NODE MANAGEMENT","level":1},{"id":"contents-click-any-row","text":"Contents — click any row","level":2},{"id":"how-scheduling-works","text":"🎯 How Scheduling Works","level":2},{"id":"the-scheduling-toolbox","text":"🧰 The Scheduling Toolbox","level":2},{"id":"taints-effects-amp-use-cases","text":"🚧 Taints — Effects &amp; Use Cases","level":2},{"id":"the-three-strategic-uses","text":"🎯 The three strategic uses","level":3},{"id":"tolerations-operators-amp-tolerationseconds","text":"🔑 Tolerations — Operators &amp; tolerationSeconds","level":2},{"id":"tolerationseconds-the-grace-timer-noexecute-only","text":"⏱️ tolerationSeconds — the grace timer (NoExecute only)","level":3},{"id":"well-known-taints-the-cluster-s-own","text":"🏥 Well-Known Taints — The Cluster's Own","level":2},{"id":"nodeselector-amp-node-affinity","text":"🧲 nodeSelector &amp; Node Affinity","level":2},{"id":"pod-affinity-amp-anti-affinity","text":"👥 Pod Affinity &amp; Anti-Affinity","level":2},{"id":"topologyspreadconstraints","text":"⚖️ topologySpreadConstraints","level":2},{"id":"priority-classes-amp-preemption","text":"👑 Priority Classes &amp; Preemption","level":2},{"id":"how-preemption-actually-fires","text":"🗡️ How preemption actually fires","level":3},{"id":"cordon-drain-amp-uncordon","text":"🛠️ Cordon, Drain &amp; Uncordon","level":2},{"id":"static-pods","text":"🪨 Static Pods","level":2},{"id":"node-affinity-required-vs-preferred","text":"🔬 Node Affinity — Required vs Preferred","level":2},{"id":"anti-affinity-prove-the-separation","text":"🔬 Anti-Affinity — Prove the Separation","level":2},{"id":"priority-amp-preemption-live","text":"🔬 Priority &amp; Preemption Live","level":2},{"id":"the-maintenance-cycle","text":"🛠️ The Maintenance Cycle","level":2},{"id":"self-check-quiz","text":"✅ Self-Check Quiz","level":2},{"id":"answer-key-scoring","text":"🗝️ Answer Key + Scoring","level":2},{"id":"glossary","text":"📚 Glossary","level":2},{"id":"one-page-cheat-sheet","text":"📄 One-Page Cheat Sheet","level":2},{"id":"what-you-can-do-now","text":"🗺️ What You Can Do Now","level":2},{"id":"you-can-now","text":"✅ You can now…","level":3}],"words":5806,"assets":[]};